using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

public class ApiTools(IHttpClientFactory httpClientFactory)
{
    [McpServerTool, Description("Fetches data from an external API for a given resource ID.")]
    public async Task<string> FetchResource(
        [Description("The resource identifier to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

public class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum number of sentences in the summary")] int? maxSentences = null)
    {
        var constraint = maxSentences.HasValue
            ? $" Use at most {maxSentences.Value} sentence(s)."
            : string.Empty;

        return new GetPromptResult
        {
            Description = "Summarization prompt",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new Content
                    {
                        Type = "text",
                        Text = $"Please provide a concise summary of the following text.{constraint}\n\n{text}"
                    }
                }
            ]
        };
    }
}

